package com.chx.claims.claim.api;
import com.chx.claims.claim.application.ClaimCommandService; import java.math.BigDecimal; import java.util.UUID; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/officer/claims") public class OfficerClaimController { private final ClaimCommandService s; public OfficerClaimController(ClaimCommandService s){this.s=s;} @PostMapping("/{id}/pick-up") public Object pick(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID officer){return s.pickUp(id,officer);} @PostMapping("/{id}/info-requests") public Object info(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID officer,@RequestParam String question){return s.requestInfo(id,officer,question);} @PostMapping("/{id}/approve") public Object approve(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID officer,@RequestParam BigDecimal amount){return s.approve(id,officer,amount);} @PostMapping("/{id}/reject") public Object reject(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID officer,@RequestParam String reason){return s.reject(id,officer,reason);} @PostMapping("/{id}/settle") public Object settle(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID officer){return s.settle(id,officer);} }
